const $=s=>document.querySelector(s),app=$('#app');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('تعذّر الحفظ. قد تكون مساحة المتصفح ممتلئة.');return false}};
let cart=read('masar-research-cart',[]),done=read('masar-research-done',[]),images=read('masar-research-images',{});let expiry=read('masar-research-expiry',0);if(!expiry){expiry=Date.now()+86400000;save('masar-research-expiry',expiry)}
const chapters=window.researchChapters;
const data=window.researchData;
const commerce=Object.freeze({shipping:500,freeShippingAt:4500,bundlePrice:5200,currency:"DZD"});
const products=[{id:'belt',name:'حزام يومي',category:'إكسسوارات',price:1200,color:'#8f5c39',kind:'belt',desc:'حزام بلون بني وإبزيم بسيط لإطلالة يومية. مقاسات تجريبية: S وM وL.'},{id:'belt-premium',name:'حزام مميز',category:'إكسسوارات',price:2000,color:'#45382e',kind:'belt',desc:'نسخة مطوّرة بتشطيب أكثر تفصيلًا وإبزيم مختلف. مثال لتجربة الأبْسيل.'},{id:'wallet',name:'محفظة كلاسيكية',category:'إكسسوارات',price:1500,color:'#805238',kind:'wallet',desc:'محفظة صغيرة لتنظيم البطاقات، تكمّل اختيار الحزام البني.'},{id:'bag',name:'حقيبة يومية',category:'حقائب',price:3000,color:'#b19b76',kind:'bag',desc:'حقيبة للدراسة بأبعاد توضيحية 42 × 30 × 12 سم ومقابض طويلة. قارِن أبعاد حاسوبك بالأبعاد قبل الاختيار؛ جميع المواصفات افتراضية.'},{id:'shirt',name:'قميص أساسي',category:'ملابس',price:1800,color:'#e3dfcc',kind:'shirt',desc:'قميص بلون محايد، مثال لتنسيق الملابس مع الإكسسوارات.'},{id:'sneakers',name:'حذاء يومي',category:'أحذية',price:4500,color:'#d2d9ce',kind:'shoe',desc:'حذاء يومي بتصميم بسيط يناسب الإطلالات غير الرسمية.'}];
const money=n=>`${n.toLocaleString('ar-DZ',{maximumFractionDigits:2})} د.ج`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function art(p){let body={belt:`<path d="M42 103 Q110 48 238 112 L232 148 Q120 88 50 135Z" fill="${p.color}"/><path d="M230 110h38v43h-38z" fill="none" stroke="#b1a18a" stroke-width="9"/><path d="M249 114v34" stroke="#b1a18a" stroke-width="5"/><path d="M60 114 Q140 75 226 126" fill="none" stroke="#fff" opacity=".22" stroke-dasharray="3 4"/>`,wallet:`<rect x="70" y="65" width="162" height="112" rx="14" fill="${p.color}"/><rect x="78" y="73" width="146" height="96" rx="10" fill="none" stroke="#d0a680" stroke-dasharray="3 4"/><path d="M185 104h57v38h-57q-15-20 0-38" fill="#643e2b"/><circle cx="206" cy="123" r="4" fill="#d4bf8b"/>`,bag:`<path d="M85 80h132l15 116H70Z" fill="${p.color}"/><path d="M115 88V61q38-49 75 0v27" fill="none" stroke="#716b4c" stroke-width="9"/><path d="M94 90l-7 92m120-92 8 92" stroke="#dac7a7" stroke-width="2"/><rect x="127" y="121" width="48" height="33" rx="3" fill="#d4c5a6"/>`,shirt:`<path d="M117 44l-58 40 30 45 25-17-5 87h93l-5-87 25 17 30-45-58-40-20 14h-38Z" fill="${p.color}" stroke="#c9c5b3" stroke-width="2"/><path d="M136 52q19 35 39 0" fill="none" stroke="#bcb9a9" stroke-width="5"/>`,shoe:`<path d="M58 148l23-62 45 28 36-18 35 40 49 16q12 3 12 22H55Z" fill="${p.color}" stroke="#a1afa0" stroke-width="2"/><path d="M53 174h205v15H51Z" fill="#fdfcf6" stroke="#b3b8ab"/><path d="M136 119l30 8m-22 0 30 8m-22 0 30 8" stroke="#fefefe" stroke-width="5"/>`}[p.kind];return `<svg viewBox="0 0 310 240" role="img" aria-label="رسم توضيحي: ${p.name}"><ellipse cx="155" cy="204" rx="100" ry="9" fill="#172c1a" opacity=".07"/>${body}</svg>`}
function visual(p,extra=''){return `<div class="product-visual ${extra}">${art(p)}<img alt="${p.name}" src="${images[p.id]||`assets/products/${p.id}.jpg`}" onerror="this.hidden=true"><span class="badge">رسم / صورة تجريبية</span></div>`}
function intro(k,t,p){return '<div class="page-intro"><div class="eyebrow"><i></i>'+k+'</div><h1>'+t+'</h1><p>'+p+'</p></div>'}
function offer(){return `<div class="offer"><div><b>ترحيب يكمّل البداية: خصم 5%</b><p>على جميع المنتجات والحزم · 24 ساعة من أول زيارة بهذا المتصفح</p><a href="#/strategy/offers" style="font-size:11px;text-decoration:underline">افهم استراتيجية العرض المحدود ←</a></div><div><div class="timer" data-timer></div><small>لا يُجدّد بعد انتهائه</small></div></div>`}
function productCard(p){return `<article class="product"><a href="#/product/${p.id}">${visual(p)}</a><div class="product-info"><p>${p.category}</p><h3><a href="#/product/${p.id}">${p.name}</a></h3><div class="price-row"><span class="price">${money(p.price)}</span><a class="text-link" href="#/product/${p.id}">التفاصيل ←</a></div><button class="btn light" data-add="${p.id}">+ أضف إلى السلة</button></div></article>`}
function bundle(){return `<div class="note"><b>حزمة الإطلالة اليومية</b><p>حزام يومي + محفظة كلاسيكية + حقيبة يومية</p><p><del>5700 د.ج</del> ← <b>5200 د.ج</b> · توفير 500 د.ج قبل الخصم الترحيبي</p><button class="btn" data-add="bundle">أضف الحزمة الكاملة +</button> <a class="text-link" href="#/strategy/bundles">شرح الاستراتيجية ←</a></div>`}
function store(){return intro('المتجر التجريبي','اختيارات بسيطة. أفكار كبيرة.','تسوّق لتتعلّم: كل عرض هنا مرتبط باستراتيجية يمكنك اكتشافها. الأسعار بوحدات نقدية افتراضية (د.ج).')+offer()+`<div class="section-head"><h2>مجموعة الاستخدام اليومي</h2><span class="demo-label">محاكاة تعليمية</span></div><div class="search-row"><select id="product-filter" aria-label="تصفية المنتجات"><option value="all">جميع المنتجات</option>${['إكسسوارات','حقائب','ملابس','أحذية'].map(t=>`<option>${t}</option>`).join('')}</select><a class="btn light" href="#/images">إدارة صور المنتجات ↗</a></div><div id="product-results" class="products">${products.map(productCard).join('')}</div><div class="section-head"><h2>اختيار واحد، مجموعة متكاملة</h2><a class="text-link" href="#/strategy/bundles">كيف تعمل الحزم؟ ←</a></div>${bundle()}`}
function policy(){return '<p>سياسة المحاكاة: الشحن 500 د.ج، ومجاني عندما يبلغ مجموع المنتجات بعد الخصومات 4500 د.ج. مدة توصيل افتراضية 3–5 أيام. مثال للاسترجاع: خلال 14 يومًا إذا كان المنتج غير مستخدم وبحالته الأصلية، عبر نموذج تواصل المتجر الفعلي. لا يُرسل هذا الموقع أي شحنة.</p>'}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return emptyPage();const similar=products.filter(x=>x.id!==id&&x.kind===p.kind),complement=products.find(x=>x.id===(p.kind==='belt'?'wallet':'belt'));return intro('المتجر / تفاصيل المنتج',p.name,p.desc)+`<div class="product-detail">${visual(p)}<div><span class="demo-label">منتج تعليمي افتراضي</span><h2 style="margin:18px 0">${money(p.price)}</h2><p class="muted">${p.desc}</p>${p.kind==='belt'?'<p>دليل مقاس توضيحي: S‏ (75–85 سم)، M‏ (85–95 سم)، L‏ (95–105 سم).</p><label>المقاس <select id="size"><option>S</option><option selected>M</option><option>L</option></select></label>':''}<div class="actions" style="margin:20px 0"><button class="btn" data-add="${p.id}" data-sized="true">أضف إلى السلة +</button><a class="btn light" href="#/cart">عرض السلة</a></div><div class="note">★★★★☆ · تقييم توضيحي للتعليم فقط<br>«اختيار عملي، ودليل المقاسات يساعد على اتخاذ القرار.»<br><a class="text-link" href="#/strategy/trust">الإثبات الاجتماعي ←</a></div></div></div>${id==='belt'?`<section class="panel related"><h2>هل يناسبك إصدار أعلى؟</h2><p>الحزام المميز بسعر 2000 بدل 1200 د.ج: فرق 800 د.ج مقابل تشطيب أكثر تفصيلًا وإبزيم مختلف. الخيار الأساسي متاح دائمًا.</p><div class="actions"><a class="btn" href="#/product/belt-premium">قارن بالحزام المميز ←</a><a class="text-link" href="#/strategy/upsell-cross">هذه استراتيجية أبسيل ↗</a></div></section>`:''}${similar.length?`<div class="section-head"><h2>منتج مشابه للمقارنة</h2><a class="text-link" href="#/strategy/upsell-cross">فهم التوصيات ←</a></div><div class="products">${similar.map(productCard).join('')}</div>`:''}<div class="section-head"><h2>يكمل اختيارك</h2><a class="text-link" href="#/strategy/upsell-cross">البيع المتقاطع — Cross-selling ←</a></div><div class="products">${productCard(complement)}</div><section class="panel related"><h2>الشحن والاسترجاع بوضوح</h2>${policy()}<a class="text-link" href="#/strategy/trust">تعلم عكس المخاطرة ←</a></section>`}
function item(id){return id==='bundle'?{id:'bundle',name:'حزمة الإطلالة اليومية',price:commerce.bundlePrice}:products.find(p=>p.id===id)}
function total(){const subtotal=cart.reduce((a,x)=>a+item(x.id).price*x.qty,0),discount=Date.now()<expiry?Math.round(subtotal*5)/100:0,net=subtotal-discount,shipping=net>=commerce.freeShippingAt||!subtotal?0:commerce.shipping;return {subtotal,discount,net,shipping,grand:net+shipping}}
function cartPage(){if(!cart.length)return intro('سلة التجربة','ابدأ باختيارك الأول.','أضف منتجات من المتجر لتكتشف أثر الحزم والخصم والشحن المجاني.')+'<a class="btn" href="#/store">استكشف المنتجات ←</a>';const t=total();return intro('المتجر / السلة','خطوة أقرب إلى فهم القرار.','راجع تفاصيل العرض. لا توجد عملية دفع حقيقية، والطلب يحفظ محليًا في هذا المتصفح.')+`<div class="detail-layout"><div><section class="panel">${cart.map((x,i)=>{let p=item(x.id);return `<div class="cart-row"><div class="name"><b>${p.name}</b><small>${x.size?'المقاس: '+safe(x.size)+' · ':''}${money(p.price)} للواحدة</small></div><div class="qty"><button data-qty="${i}" data-delta="-1" aria-label="تقليل كمية ${p.name}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="زيادة كمية ${p.name}">+</button></div><b>${money(p.price*x.qty)}</b><button class="btn light" data-remove="${i}" aria-label="حذف ${p.name}">حذف</button></div>`}).join('')}</section><section class="panel"><h3>${t.net>=commerce.freeShippingAt?'✓ وصلت إلى الشحن المجاني':`باقي ${money(commerce.freeShippingAt-t.net)} للوصول إلى الشحن المجاني`}</h3><div class="progress"><i style="width:${Math.min(100,t.net/commerce.freeShippingAt*100)}%"></i></div><p>يُحسب الحد بعد خصم المنتجات. الشحن العادي 500 د.ج.</p><a class="text-link" href="#/strategy/bundles">افهم استراتيجية حد الشحن ←</a></section><section class="panel"><h3>هل نسيت إكمال اختيارك؟</h3><p>هذا تذكير داخلي بالسلة المحفوظة، مثال لتذكير السلات المتروكة.</p><a class="text-link" href="#/strategy/offers">اقرأ الاستراتيجية ←</a></section></div><aside><section class="panel totals"><h2>ملخص التجربة</h2><div><span>قيمة المنتجات</span><b>${money(t.subtotal)}</b></div><div><span>خصم ترحيبي 5%</span><b>− ${money(t.discount)}</b></div><div><span>الشحن</span><b>${money(t.shipping)}</b></div><div class="grand"><span>الإجمالي</span><span>${money(t.grand)}</span></div><small class="muted">${Date.now()<expiry?'الخصم سارٍ ويشمل الحزم.':'انتهى العرض الترحيبي.'}</small><button class="btn" style="width:100%;margin-top:18px" id="checkout">تأكيد طلب تجريبي ←</button><p>طلب تعليمي دون دفع حقيقي.</p></section></aside></div><div class="section-head"><h2>مكمّل بسيط لاختيارك</h2><a class="text-link" href="#/strategy/upsell-cross">شرح البيع المتقاطع ←</a></div><div class="products">${productCard(products.find(p=>!cart.some(x=>x.id===p.id||(x.id==='bundle'&&['belt','wallet','bag'].includes(p.id))))||products[2])}</div>`}
function metricsBase(){const orders=read('masar-research-orders',[]);return intro('مختبر القياس','لا تكتفِ بالفكرة. اختبرها بالأرقام.','حاسبات تعليمية ببيانات قابلة للتعديل. لا تُجمع زيارات حقيقية، ونتائج الطلبات التجريبية تخص هذا المتصفح فقط.')+`<section class="panel"><h2>قارن نسختين A/B</h2><p>الأرقام الأولية افتراضية. الاختبار الحقيقي يحتاج توزيعًا مناسبًا وتحليلًا إحصائيًا.</p><div class="calculator"><label>زيارات A<input type="number" id="av" min="1" value="1000"></label><label>طلبات A<input type="number" id="ao" min="0" value="30"></label><label>زيارات B<input type="number" id="bv" min="1" value="1000"></label><label>طلبات B<input type="number" id="bo" min="0" value="40"></label></div><div id="ab-result" class="result" aria-live="polite"></div></section><section class="panel"><h2>متوسط قيمة الطلب وتكرار الشراء</h2><div class="calculator"><label>إجمالي الإيراد<input id="revenue" type="number" min="0" value="180000"></label><label>عدد الطلبات<input id="orders" type="number" min="1" value="60"></label><label>عدد العملاء المشترين<input id="customers" type="number" min="1" value="50"></label><label>عملاء لديهم طلبان فأكثر<input id="repeat" type="number" min="0" value="10"></label></div><div id="aov-result" class="result" aria-live="polite"></div><div class="note">نسبة العملاء المكررين تختلف عن عدد الطلبات لكل عميل. استخدم فترة زمنية واحدة في المقارنة.</div></section><section class="panel"><h2>سجل تجربتك المحلية</h2><div class="stats"><div><b>${orders.length}</b><p>طلبات تجريبية</p></div><div><b>${money(orders.reduce((a,o)=>a+o.net,0))}</b><p>قيمة منتجات بعد الخصم</p></div><div><b>${money(orders.length?orders.reduce((a,o)=>a+o.net,0)/orders.length:0)}</b><p>متوسط الطلب دون الشحن</p></div></div><p>لا نحسب معدل تحويل أو عودة حقيقيًا من هذا السجل؛ لا توجد هوية عملاء أو تحليلات زيارات.</p>${orders.slice(-5).reverse().map(o=>`<div class="cart-row"><span>طلب تجريبي · ${new Date(o.time).toLocaleDateString('ar')}</span><b>${money(o.net)} دون الشحن</b></div>`).join('')}</section>`}
function imagePage(){return intro('مكتبة الصور','كل صورة، في مكانها المناسب.','ارفع صورة للمنتج لتظهر تلقائيًا في المتجر وصفحته. الصور المرفوعة تُحفظ في هذا المتصفح فقط؛ لن تظهر لدى الطلاب الآخرين إلا عند إدراجها في ملفات الموقع وإعادة نشره.')+`<div class="note" style="margin-bottom:24px">لصور ثابتة في ملفات الموقع: ضع الصور داخل <code dir="ltr">dist/assets/products/</code> بالأسماء أدناه، ثم أعد نشر الموقع. يُفضّل حجم مربع 1000 × 1000 بكسل. الرفع المحلي يقبل JPEG وPNG وWebP حتى 2 ميغابايت، ويمكن تنزيل قائمة الأسماء.</div><button class="btn light" id="download-names" style="margin-bottom:20px">تنزيل دليل أسماء الصور ↓</button><div class="upload-grid">${products.map(p=>`<article class="upload-card">${visual(p)}<h3 style="margin-top:12px">${p.name}</h3><code>${p.id}.jpg</code><label>اختر صورة<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${p.id}" aria-label="رفع صورة ${p.name}"></label>${images[p.id]?`<button class="btn light" data-reset-image="${p.id}">إزالة الصورة المحلية</button>`:''}</article>`).join('')}</div>`}
function emptyPage(){return '<div class="empty"><h2>هذه الصفحة غير موجودة</h2><a class="btn" href="#/">عد إلى البداية ←</a></div>'}
let route='';function render(){const parts=(location.hash.slice(2)||'').split('/');route=parts[0]||'home';const pages={home,research,terms,learn:()=>learn(parts[1]),strategy:()=>detail(parts[1]),store,product:()=>productPage(parts[1]),cart:cartPage,metrics,images:imagePage};app.innerHTML=(pages[route]||emptyPage)();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(['product','cart'].includes(route)?'store':route==='strategy'?'learn':route)));$('#breadcrumb').textContent='مساحتك التعليمية / '+({home:'مدخل البحث',learn:'المباحث والمطالب',strategy:'شرح المطلب',store:'المتجر التجريبي',product:'تفاصيل المنتج',cart:'سلة التجربة',metrics:'مختبر القياس',images:'مكتبة الصور',research:'الخطة والنص الكامل',terms:'المصطلحات العربية والإنجليزية'}[route]||'صفحة');$('#cart-count').textContent=cart.reduce((a,x)=>a+x.qty,0);if(route==='metrics')calculate();tick();window.scrollTo(0,0)}
function calculateBase(){if(!$('#av'))return;let [av,ao,bv,bo]=['av','ao','bv','bo'].map(id=>Number($('#'+id).value));$('#ab-result').innerHTML=av<=0||bv<=0||ao<0||bo<0||ao>av||bo>bv||![av,ao,bv,bo].every(Number.isInteger)?'أدخل أعدادًا صحيحة: الزيارات أكبر من صفر، والطلبات بين صفر وعدد الزيارات.':`تحويل A: ${(ao/av*100).toFixed(2)}% · تحويل B: ${(bo/bv*100).toFixed(2)}%<b>${ao?`الرفع النسبي: ${((bo/bv-ao/av)/(ao/av)*100).toFixed(2)}%`:'لا يُحسب الرفع النسبي عندما يكون تحويل A صفرًا.'}</b><small>هذه مقارنة وصفية، وليست حكمًا بالدلالة الإحصائية.</small>`;let [r,o,c,re]=['revenue','orders','customers','repeat'].map(id=>Number($('#'+id).value));$('#aov-result').innerHTML=r<0||o<=0||c<=0||re<0||re>c||![o,c,re].every(Number.isInteger)?'راجع القيم: أعداد صحيحة موجبة للطلبات والعملاء، والمكررون لا يتجاوزون العملاء.':`متوسط قيمة الطلب<b>${money(r/o)}</b>نسبة العملاء المكررين: ${(re/c*100).toFixed(1)}%`}
function tick(){const active=Date.now()<expiry,expired=window.wasActive&&!active;window.wasActive=active;document.querySelectorAll('[data-timer]').forEach(el=>{const t=Math.max(0,Math.floor((expiry-Date.now())/1000));el.textContent=t?String(Math.floor(t/3600)).padStart(2,'0')+' : '+String(Math.floor(t%3600/60)).padStart(2,'0')+' : '+String(t%60).padStart(2,'0'):'انتهى العرض'});if(expired&&['cart','store','product'].includes(route))render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add){let size=b.dataset.sized&&$('#size')?$('#size').value:undefined;const old=cart.find(x=>x.id===b.dataset.add&&x.size===size);if(old)old.qty++;else cart.push({id:b.dataset.add,qty:1,...(size?{size}:{})});save('masar-research-cart',cart);$('#cart-count').textContent=cart.reduce((a,x)=>a+x.qty,0);toast('أُضيف إلى السلة التجريبية');if(route==='cart')render()}
if(b.dataset.qty!==undefined){const i=+b.dataset.qty;cart[i].qty+=+b.dataset.delta;if(cart[i].qty<=0)cart.splice(i,1);save('masar-research-cart',cart);render()}if(b.dataset.remove!==undefined){cart.splice(+b.dataset.remove,1);save('masar-research-cart',cart);render()}if(b.dataset.done){done=done.includes(b.dataset.done)?done.filter(x=>x!==b.dataset.done):[...done,b.dataset.done];save('masar-research-done',done);render()}if(b.dataset.segment){document.querySelectorAll('[data-segment]').forEach(x=>x.classList.toggle('selected',x===b));$('#segment-message').textContent=b.dataset.segment==='new'?'أهلًا بك! اكتشف المنتجات وتعرّف على سياسة الشحن والاسترجاع.':'مرحبًا بعودتك! قارن قطعًا تكمل اختيارك السابق.'}
if(b.id==='checkout'){const t=total(),orders=read('masar-research-orders',[]);orders.push({time:Date.now(),net:t.net,total:t.grand,items:cart});if(!save('masar-research-orders',orders))return;cart=[];save('masar-research-cart',cart);render();app.innerHTML=intro('اكتملت المحاكاة','طلب تجريبي ناجح ✓','لم يُخصم أي مبلغ ولم يُرسل أي طلب إلى متجر حقيقي.')+'<div class="success"><h2>تم حفظ تجربتك</h2><p>قيمة الطلب مع الشحن: '+money(t.grand)+'</p><p>راجع في المختبر كيف أثّر الطلب على متوسط قيمة السلة.</p><a class="btn" href="#/metrics">شاهد النتائج ←</a></div>'}
if(b.dataset.resetImage){delete images[b.dataset.resetImage];save('masar-research-images',images);render()}if(b.id==='download-names'){const txt='دليل صور مسار\nضع الصور في dist/assets/products/ ثم أعد نشر الموقع.\n'+products.map(p=>p.id+'.jpg — '+p.name).join('\n')+'\nالرفع داخل الموقع يحفظ نسخة محلية في المتصفح فقط.';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+txt],{type:'text/plain;charset=utf-8'}));a.download='masar-research-image-guide.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}});
document.addEventListener('input',e=>{if(e.target.id==='search')filterLessons();if(route==='metrics')calculate()});
function filterLessons(){const q=$('#search').value.trim().toLowerCase(),ch=$('#chapter-filter').value;const found=data.filter(s=>(ch==='all'||s.ch===+ch)&&(s.title+' '+s.en+' '+s.intro).toLowerCase().includes(q));$('#strategy-results').innerHTML=found.length?found.map(strategyRow).join(''):'<div class="empty">لم نجد استراتيجية بهذا الاسم.</div>'}
document.addEventListener('change',async e=>{if(e.target.id==='chapter-filter')filterLessons();if(e.target.dataset.upload){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2097152){toast('اختر JPEG أو PNG أو WebP بحجم لا يتجاوز 2 ميغابايت.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const canvas=document.createElement('canvas'),ratio=Math.min(1,1000/im.width,1000/im.height);canvas.width=im.width*ratio;canvas.height=im.height*ratio;canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const id=e.target.dataset.upload,next={...images,[id]:canvas.toDataURL('image/jpeg',.82)};if(save('masar-research-images',next)){images=next;render();toast('تم حفظ الصورة في هذا المتصفح وظهرت في مكانها.')}};im.onerror=()=>toast('تعذّر قراءة هذه الصورة.');im.src=reader.result};reader.readAsDataURL(file)}});
const ordinals=['الأول','الثاني','الثالث','الرابع'];
const quizOptions=[['لأن الزيارات وحدها لا توضّح الشراء ولا أسباب المغادرة.','لأن كل زيارة تعني عملية شراء.','لأن متوسط السلة يساوي عدد الزيارات.'],['نبدأ بتشخيص العائق ثم نختبر تحسينًا مناسبًا.','نغيّر لون الزر دائمًا قبل أي تشخيص.','نضيف خطوات أكثر لإتمام الطلب.'],['عرض بشروط حقيقية ومهلة لا تتجدد عند التحديث.','تقييمات مختلقة لتشجيع المتردد.','مخزون منخفض يظهر حتى بلا بيانات.'],['نقرأ المتوسط مع التحويل والتكاليف والربح.','يكفي ارتفاع المتوسط مهما انخفضت الطلبات.','نعتبر تكلفة الشحن المجاني صفرًا على المتجر.']];
function chapterCard(c,i){return `<a class="chapter" href="#/learn/${i}"><div class="chapter-top"><span class="chapter-number">المبحث ${ordinals[i]}</span><span class="student-role">مساحة الطالب ${ordinals[i]}</span></div><h3>${c.title}</h3><p>${c.desc}</p><div class="chips">${c.tags.map(t=>`<span class="chip">${t}</span>`).join('')}</div><div class="chapter-bottom"><span>3 مطالب · مثال تطبيقي · سؤال مراجعة</span><span>ابدأ المبحث ←</span></div></a>`}
function chapterLine(ch){return `<div class="chapter-line no-print">${chapters.map((c,i)=>`<a href="#/learn/${i}" class="${i===ch?'active':''}"><b>المبحث ${ordinals[i]}</b>${['نفهم الزائر','نحسّن التجربة','نبني الثقة','نطوّر قيمة الطلب'][i]}</a>`).join('')}</div>`}
function home(){return `<section class="research-hero"><div><span class="research-kicker">بحث جامعي تفاعلي · لأربعة طلاب</span><h1>تحويل الزوار إلى عملاء<br>وتطوير متوسط سلة الشراء</h1><p>من أول زيارة إلى طلب ذي قيمة: بحث مترابط نفهم فيه سلوك الزائر، ونزيل عوائق الشراء، ونبني الثقة، ثم نقيس أثر الاستراتيجيات.</p><div class="actions"><a class="btn" href="#/learn/0">ابدأ المبحث الأول ←</a><a class="btn outline" href="#/research">خطة البحث والنص الكامل ▤</a></div></div><div class="story-card"><div class="portrait">س</div><span class="eyebrow">القصة التي تجمع بحثنا</span><h3 style="margin-top:9px">سارة تبحث عن حقيبة للدراسة.</h3><p>ما الذي يساعدها على الاختيار؟ ما الذي يمنعها من الطلب؟ ومتى تكون الإضافة مفيدة لها؟ سنجيب مع كل مبحث.</p><div class="story-path">زيارة ← فهم ومقارنة ← ثقة وشراء ← قيمة إضافية</div></div></section><section class="research-problem"><div><span class="eyebrow">السؤال الذي يقود البحث</span><h2 style="margin-top:10px">من الزيارة إلى القيمة</h2></div><p>كيف يمكن للمتجر الإلكتروني تحويل زواره إلى عملاء، وتطوير متوسط قيمة سلة الشراء من خلال تحسين تجربة المستخدم وتطبيق استراتيجيات تسويقية مناسبة؟</p></section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><b>04</b><small>مباحث لأربعة طلاب</small></div></div><div class="stat"><span class="stat-icon">⌁</span><div><b>12</b><small>مطلبًا مترابطًا</small></div></div><div class="stat"><span class="stat-icon">↗</span><div><b>01</b><small>قصة تطبيقية مشتركة</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><b>${done.length}<small> / 12</small></b><small>تقدمك في القراءة</small></div></div></div><div class="section-head"><div><h2>أربعة مباحث، فكرة تتكامل.</h2><p>لكل طالب ثلاثة مطالب. يبدأ كل جزء من حيث انتهى الذي قبله.</p></div></div><div class="grid">${chapters.map(chapterCard).join('')}</div><section class="panel" style="margin-top:25px"><h2>كيف تستخدمون الموقع في العرض؟</h2><div class="map"><span>اشرحوا الفكرة</span><em>←</em><span>اربطوها بقصة سارة</span><em>←</em><span>جرّبوها في المتجر</span><em>←</em><span>ناقشوا النتيجة</span></div><p>كل مطلب يتضمن شرحًا ومثالًا وخطوات تطبيق وخلاصة، مع ملاحظات تساعد الطالب على تقديمه. يمكن تفعيل وضع العرض، أو فتح النص الكامل وطباعته.</p></section><div class="bottom-banner"><div><h3>المتجر يخدم الشرح.</h3><p>جرّب صفحة المنتج والسلة والحزمة، ثم ارجع للمطلب الذي يشرح سبب استخدامها.</p></div><a class="btn" href="#/store">افتح التطبيق العملي ←</a></div>`}
function strategyRow(s){return `<div class="strategy"><span class="num">${s.ch+1}.${s.i%3+1}</span><div><span class="lesson-title-number">المبحث ${ordinals[s.ch]} · المطلب ${ordinals[s.i%3]}</span><h3>${s.title} ${done.includes(s.id)?'✓':''}</h3><bdi class="term-en">${s.en}</bdi><p>${s.intro}</p></div><a class="btn light" href="#/strategy/${s.id}">اقرأ المطلب ←</a></div>`}
function learn(ch){if(ch!==undefined&&(!/^\d$/.test(ch)||!chapters[+ch]))return emptyPage();if(ch===undefined)return intro('المباحث والمطالب','خطة واضحة. شرح يمشي معك.','اختر مبحثًا أو ابحث عن مطلب. يتدرج البحث من تشخيص سلوك الزائر إلى قياس أثر تحسين قيمة الطلب.')+`<div class="grid">${chapters.map(chapterCard).join('')}</div><div class="search-row"><input id="search" type="search" placeholder="ابحث عن استراتيجية…" aria-label="البحث عن مطلب"><select id="chapter-filter" aria-label="اختيار المبحث"><option value="all">جميع المباحث</option>${chapters.map((c,i)=>`<option value="${i}">${c.title}</option>`).join('')}</select></div><div id="strategy-results" class="strategy-list">${data.map(strategyRow).join('')}</div>`;const i=+ch,c=chapters[i];return intro(`مساحة الطالب ${ordinals[i]} · المبحث ${ordinals[i]}`,c.title,c.desc)+chapterLine(i)+`<div class="chapter-story"><strong>قصة سارة<br>المرحلة ${i+1}</strong><p>${c.story}</p></div><div class="section-head"><h2>مطالب المبحث</h2><span class="show-all-label">اشرح المفهوم، ثم انتقل إلى المثال</span></div><div class="strategy-list">${data.filter(s=>s.ch===i).map(strategyRow).join('')}</div><section class="panel" style="margin-top:22px"><h2>تطبيق يجمع المبحث</h2>${chapterApplication(i)}</section>${quiz(i)}<div class="key-idea"><small>جسر إلى الفكرة التالية</small>${c.bridge}</div><div class="nav-pair">${i>0?`<a class="btn light" href="#/learn/${i-1}">→ المبحث السابق</a>`:'<a class="btn light" href="#/">→ مدخل البحث</a>'}${i<3?`<a class="btn" href="#/learn/${i+1}">المبحث التالي ←</a>`:'<a class="btn" href="#/research">الخاتمة والنص الكامل ←</a>'}</div>`}
function chapterApplication(i){if(i===0)return '<p class="explanation">ارسموا رحلة سارة، ثم اكتبوا تحت كل خطوة سؤالها والعائق المحتمل. مثال: عند صفحة المنتج تسأل «هل تتسع الحقيبة لحاسوبي؟» والعائق هو غياب الأبعاد.</p><div class="map"><span>منشور: هل يناسب حاجتي؟</span><em>←</em><span>المنتج: هل المقاس مناسب؟</span><em>←</em><span>السلة: ما التكلفة النهائية؟</span><em>←</em><span>الطلب: هل أؤكّد؟</span></div>';if(i===1)return beforeAfter();if(i===2)return '<p class="explanation">اعرضوا مخاوف سارة على الطلاب: موعد الوصول، وإمكانية الاسترجاع، وصدق العرض. اطلبوا منهم تحديد المعلومة التي تجيب عن كل خوف، ثم افتحوا صفحة المنتج لمراجعة السياسة.</p><a class="btn" href="#/product/bag">افتح حقيبة سارة ←</a>';return '<p class="explanation">قارنوا شراء الحقيبة منفردة بشراء الحزمة. ثم ناقشوا: هل تحتاج سارة كل القطع؟ هل التوفير واضح؟ وما التكلفة التي يتحملها المتجر؟</p>'+bundle()}
function quiz(i){return `<section class="quiz"><span class="eyebrow">توقّف للنقاش · سؤال المبحث ${ordinals[i]}</span><h3>${chapters[i].question}</h3><div class="quiz-options">${quizOptions[i].map((t,j)=>`<button data-quiz="${i}" data-answer="${j}">${t}</button>`).join('')}</div><div id="quiz-feedback-${i}" class="quiz-feedback" role="status" aria-live="polite"></div></section>`}
function detail(id){const s=data.find(x=>x.id===id);if(!s)return emptyPage();const next=data[s.i+1],prev=data[s.i-1];return intro(`المبحث ${ordinals[s.ch]} / المطلب ${ordinals[s.i%3]}`,s.title,s.intro)+`<div class="read-summary"><span>◷ قراءة متأنية ثم تطبيق</span><span>مساحة الطالب ${ordinals[s.ch]}</span><span>${s.en}</span></div><div class="detail-layout lesson-detail"><div><section class="panel">${s.explain.map(([h,p])=>`<div class="lesson-part"><h2>${h}</h2><p class="explanation">${p}</p></div>`).join('')}</section><section class="panel"><h2>لنقرّب الفكرة بمثال</h2><div class="example-box"><b>مثال تعليمي مرتبط ببحثنا</b>${s.example}</div><div class="map">${s.map.map((t,i)=>`${i?'<em>←</em>':''}<span>${t}</span>`).join('')}</div></section><section class="panel"><h2>كيف نطبّقها خطوة بخطوة؟</h2><ol class="steps">${s.steps.map(t=>`<li>${t}</li>`).join('')}</ol><div class="note">${s.note}</div></section><section class="panel"><h2>جرّب الفكرة أو ناقشها</h2>${demo(s)}</section><section class="panel"><h2>بماذا نقيس النتيجة؟</h2><div class="formula">${s.metric}</div><details class="presenter-notes"><summary>ملاحظات للطالب أثناء العرض</summary><ul><li>ابدأ بالسؤال: ${['ما الذي نحتاج معرفته عن سلوك سارة؟','كيف نجعل تجربة سارة أوضح وأسهل؟','ما الذي تحتاجه سارة لتطمئن للشراء؟','هل يضيف هذا الاقتراح قيمة فعلية لسارة؟'][s.ch]}</li><li>اشرح الفكرة بكلماتك، ثم استخدم المثال أعلاه بدل قراءة النص كاملًا.</li><li>افتح التطبيق واطلب من الطلاب وصف ما تغير ولماذا.</li><li>اختم بهذه الفكرة: ${s.takeaway}</li></ul></details></section><div class="key-idea"><small>الخلاصة التي نريد تذكّرها</small>${s.takeaway}</div><div class="nav-pair">${prev?`<a class="btn light" href="#/strategy/${prev.id}">→ المطلب السابق</a>`:'<a class="btn light" href="#/learn/0">→ بداية المبحث</a>'}${next?`<a class="btn" href="#/strategy/${next.id}">المطلب التالي ←</a>`:'<a class="btn" href="#/research">الخاتمة ←</a>'}</div></div><aside><div class="panel sticky"><span class="eyebrow">بطاقة المطلب ${s.ch+1}.${s.i%3+1}</span><h3 style="margin-top:14px">افهم، اشرح، ثم جرّب.</h3><p>لا تحتاج حفظ كل النص. اشرح الفكرة والمثال والخلاصة.</p><button class="btn" data-done="${s.id}">${done.includes(s.id)?'✓ أتممت هذا المطلب':'علّم المطلب كمكتمل'}</button><a class="btn light" href="#/learn/${s.ch}">مطالب المبحث ←</a><a class="btn light" href="#/store">المتجر التجريبي ↗</a><div class="progress"><i style="width:${done.length/12*100}%"></i></div><p>${done.length} من 12 مطلبًا مكتملًا<br>محفوظة في هذا المتصفح</p></div></aside></div>`}
function beforeAfter(){return `<div class="case-lab"><div class="case-version"><b>قبل التحسين · مثال مكتوب</b><h3>«حقيبة رائعة»</h3><p>صورة بلا مقاس، وصف عام، وتكلفة توصيل لا تظهر إلا في النهاية.</p><p>سؤال سارة الذي بقي بلا إجابة: هل تتسع لحاسوبي؟</p></div><div class="case-version good"><b>بعد التحسين · مثال مكتوب</b><h3>حقيبة للدراسة بأبعاد واضحة</h3><p>مواصفات وأبعاد، سعر وتكلفة توصيل معلنان، وزر يوضح الخطوة التالية.</p><p>الفائدة: تستطيع سارة المقارنة واتخاذ قرار مستنير.</p></div></div><p class="case-arrow">هذه مقارنة تصميمية توضيحية، وليست نتيجة اختبار فعلي.</p><a class="btn" href="#/product/bag">افتح صفحة الحقيبة ←</a>`}
function demo(s){switch(s.demo){case 'journey':return '<div class="note">نشاط جماعي: أين يمكن أن تتوقف سارة إذا لم تجد أبعاد الحقيبة؟ أضيفوا خطوة أو معلومة تعالج هذا العائق.</div>';case 'leaks':return '<p>100 جلسة للمنتج ← 40 سلة ← 10 طلبات. أكبر تسرب نسبي هنا بين السلة والطلب: 75%.</p><div class="heatmap">'+['الصورة','الأبعاد','الوصف','الشحن','الزر','35%','18%','12%','15%','20%'].map((t,i)=>`<span style="background:${['#f0dca7','#dce9d0','#f4e5c9','#e5b77b','#e99165'][i%5]}">${t}</span>`).join('')+'</div><small class="muted">خريطة افتراضية لمناقشة مواضع التفاعل؛ ليست تسجيلًا للزوار.</small>';case 'cta':return beforeAfter();case 'risk':return policy()+'<a class="btn light" href="#/product/bag">راجع موضع السياسة في صفحة المنتج ←</a>';case 'offer':return offer();case 'recovery':return '<div class="note"><b>معاينة تذكير، لا رسالة مرسلة</b><p>«حقيبتك ما زالت في السلة. راجعي تكلفة التوصيل وسياسة الاسترجاع قبل إكمال اختيارك.»</p></div><p>للمناقشة: متى تكون هذه الرسالة مفيدة؟ ومتى يصبح تكرارها مزعجًا؟</p><a class="btn light" href="#/cart">افتح السلة المحفوظة ←</a>';case 'upsell':return '<div class="case-lab"><div class="case-version good"><b>البيع الإضافي — Upselling</b><p>حزام مميز 2000 د.ج بدل الأساسي 1200 د.ج. فرق 800 د.ج مقابل خصائص موضحة.</p></div><div class="case-version good"><b>البيع المتقاطع — Cross-selling</b><p>محفظة 1500 د.ج مع الحزام. منتج مختلف يكمل الاستخدام.</p></div></div><p><a class="btn" href="#/product/belt">جرّب المثال في صفحة الحزام ←</a></p>';case 'bundle':return bundle();case 'metrics':return '<p>غيّر عدد الزيارات والطلبات، ثم قارن التحويل ومتوسط الطلب وتكلفة العرض في المختبر.</p><a class="btn" href="#/metrics">افتح حاسبات القياس ←</a>';case 'cart':return '<a class="btn" href="#/cart">راجع السلة والتكلفة النهائية ←</a>';default:return '<p>اختر قسم الحقائب ثم افتح حقيبة سارة. لاحظ سهولة الوصول والمعلومات التي تساعد الاختيار.</p><a class="btn" href="#/store">افتح المتجر ←</a>'}}
function research(){return intro('الخطة والنص الكامل','تحويل الزوار إلى عملاء وتطوير متوسط سلة الشراء','نسخة للقراءة والعرض والطباعة، وفق الخطة المعتمدة: أربعة مباحث وثلاثة مطالب لكل مبحث.')+`<div class="actions no-print" style="margin-bottom:23px"><button class="btn" id="print-research">طباعة البحث / حفظ PDF ↓</button><a class="btn light" href="#/learn/0">القراءة مطلبًا بمطلب ←</a></div><section class="panel"><h2>مقدمة</h2><p class="explanation">تواجه المتاجر الإلكترونية تحديين مترابطين: إقناع الزائر بإتمام عملية الشراء، وزيادة قيمة الطلب من خلال تقديم منتجات وعروض تناسب حاجته. لذلك لا يكفي جذب الزيارات؛ بل يجب فهم سلوك الزائر وتحسين تجربته وبناء ثقته، ثم تقديم قيمة إضافية مناسبة وقياس نتائجها.</p><h2 style="margin-top:24px">إشكالية البحث</h2><p class="explanation">كيف يمكن للمتجر الإلكتروني تحويل زواره إلى عملاء، وتطوير متوسط قيمة سلة الشراء من خلال تحسين تجربة المستخدم وتطبيق استراتيجيات تسويقية مناسبة؟</p><h2 style="margin-top:24px">أهداف البحث</h2><ol class="steps"><li>توضيح الفرق بين معدل التحويل ومتوسط قيمة الطلب.</li><li>فهم رحلة الزائر وتشخيص العوائق التي تمنعه من الشراء.</li><li>شرح دور تجربة المستخدم والثقة والحوافز في إتمام الطلب.</li><li>تطبيق استراتيجيات زيادة قيمة الطلب وتقييم أثرها مع التكاليف.</li></ol><div class="note">المنهج التعليمي: شرح مفاهيمي، ثم حالة افتراضية مشتركة وتجارب حسابية. هذا الموقع لا يعرض نتائج دراسة ميدانية أو بيانات عملاء حقيقية.</div></section><div class="research-toc">${chapters.map((c,i)=>`<article><span class="eyebrow">المبحث ${ordinals[i]} · الطالب ${ordinals[i]}</span><h3 style="margin-top:10px"><a href="#/learn/${i}">${c.title}</a></h3><ol>${data.filter(s=>s.ch===i).map(s=>`<li><a href="#/strategy/${s.id}">${s.title}</a></li>`).join('')}</ol></article>`).join('')}</div>${chapters.map((c,i)=>`<section class="print-chapter"><h2>المبحث ${ordinals[i]}: ${c.title}</h2><p>${c.story}</p>${data.filter(s=>s.ch===i).map(s=>`<article class="print-lesson"><span class="lesson-title-number">المطلب ${ordinals[s.i%3]}</span><h3>${s.title}</h3><p>${s.intro}</p>${s.explain.map(([h,p])=>`<h4>${h}</h4><p>${p}</p>`).join('')}<div class="example-box"><b>مثال</b>${s.example}</div><h4>القياس</h4><p>${s.metric}</p><div class="note">${s.note}</div><p style="margin-top:15px"><b>الخلاصة:</b> ${s.takeaway}</p><a class="text-link no-print" href="#/strategy/${s.id}">افتح الشرح والتطبيق التفاعلي ←</a></article>`).join('')}</section>`).join('')}<section class="research-conclusion"><h2>خاتمة البحث</h2><p>يتكامل تحويل الزوار إلى عملاء مع تطوير متوسط قيمة الطلب، لكن لكل هدف مؤشره واستراتيجياته. يبدأ العمل بفهم حاجة الزائر ورحلته، ثم إزالة صعوبات الاستخدام وتوفير معلومات موثوقة تقلل تردده. وبعد ذلك يمكن تقديم ترقية أو منتج مكمل أو حزمة، بشرط أن تكون ملائمة وواضحة واختيارية.</p><p>ولا تكتمل الاستراتيجية دون قياس: نتابع التحويل وقيمة الطلب والتكاليف معًا، ونختبر الفرضيات بدل افتراض نجاحها. ويمكن لاحقًا توسيع البحث إلى الولاء وتكرار الشراء بوصفهما امتدادًا للعلاقة مع العميل.</p><h3>توصيات عملية</h3><p>شخّص قبل التعديل، أظهر التكلفة مبكرًا، استخدم تقييمات وعروضًا صادقة، اقترح ما يخدم الحاجة، ثم راجع النتائج والربحية.</p></section><div class="note">المحتوى صياغة تعليمية مبنية على خطة البحث المتفق عليها، وليس مراجعة أكاديمية موثقة بالمراجع. عند تسليم بحث رسمي، تُضاف المراجع وفق متطلبات الأستاذ، ولا تُنسب الأمثلة الافتراضية إلى دراسة فعلية.</div>`}
function metrics(){return metricsBase()+`<section class="panel"><h2>هل العرض مجدٍ؟ حاسبة هامش المساهمة</h2><p>أدخل قيمًا افتراضية للطلب الواحد. نحسب الإيراد بعد الخصم ثم نطرح تكلفة المنتجات والشحن الذي يتحمله المتجر.</p><div class="calculator"><label>قيمة المنتجات قبل الخصم<input id="margin-price" type="number" min="0" value="5200"></label><label>الخصم %<input id="margin-discount" type="number" min="0" max="100" value="5"></label><label>تكلفة المنتجات<input id="margin-cost" type="number" min="0" value="3500"></label><label>الشحن الذي يتحمله المتجر<input id="margin-shipping" type="number" min="0" value="500"></label></div><div id="margin-result" class="result" aria-live="polite"></div><p class="policy-note">هذا هامش مبسط قبل التسويق والعمولات والتكاليف الثابتة والضرائب وغيرها. لا يُعد صافي ربح.</p></section>`}
function calculate(){calculateBase();if(!$('#margin-price'))return;const [p,d,c,s]=['margin-price','margin-discount','margin-cost','margin-shipping'].map(id=>Number($('#'+id).value));$('#margin-result').innerHTML=[p,d,c,s].some(x=>!Number.isFinite(x)||x<0)||d>100?'أدخل قيمًا موجبة أو صفرًا، ونسبة خصم من 0 إلى 100.':`<div class="margin-result"><div>الإيراد بعد الخصم<b>${money(p*(1-d/100))}</b></div><div>هامش المساهمة المبسط<b>${money(p*(1-d/100)-c-s)}</b></div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.quiz!==undefined){const i=+b.dataset.quiz,correct=+b.dataset.answer===0;document.querySelectorAll(`[data-quiz="${i}"]`).forEach(x=>x.classList.toggle('selected',x===b));$('#quiz-feedback-'+i).textContent=(correct?'✓ إجابة موفقة. ':'لنفكّر فيها مرة أخرى. ')+chapters[i].answer}if(b.id==='presentation-toggle'){const active=document.body.classList.toggle('presentation');b.setAttribute('aria-pressed',String(active));b.textContent=active?'إنهاء وضع العرض ◱':'وضع العرض ◱'}if(b.id==='print-research')window.print()});

const extraProducts=[
{id:'backpack',name:'حقيبة ظهر جامعية',category:'حقائب',price:4000,color:'#60796c',kind:'backpack',desc:'حقيبة ظهر بجيوب متعددة وحمالات قابلة للتعديل. أبعاد توضيحية 45 × 32 × 15 سم؛ بديل أكبر للحقيبة اليومية.'},
{id:'hoodie',name:'سترة بغطاء رأس',category:'ملابس',price:3500,color:'#738681',kind:'hoodie',sizes:['S','M','L','XL'],desc:'سترة يومية بغطاء رأس وجيب أمامي. اختر المقاس قبل الإضافة؛ المواصفات للتوضيح.'},
{id:'cap',name:'قبعة قطنية',category:'إكسسوارات',price:900,color:'#a98c68',kind:'cap',desc:'قبعة بلون محايد وحزام خلفي قابل للتعديل؛ قطعة مكملة للإطلالة اليومية.'},
{id:'watch',name:'ساعة بتصميم بسيط',category:'إكسسوارات',price:3000,color:'#424f49',kind:'watch',desc:'ساعة بعقارب وسوار داكن للتنسيق مع الحزام. مثال تعليمي لمنتج مكمل.'},
{id:'bottle',name:'قارورة ماء للدراسة',category:'لوازم الدراسة',price:1200,color:'#839a93',kind:'bottle',desc:'قارورة قابلة لإعادة الاستخدام بسعة توضيحية 600 مل، مناسبة للحمل في حقيبة الدراسة.'},
{id:'notebook',name:'دفتر ملاحظات',category:'لوازم الدراسة',price:400,color:'#b08360',kind:'notebook',desc:'دفتر بغلاف بسيط ومقاس توضيحي A5. مثال لإضافة منخفضة القيمة تخدم حاجة الدراسة.'}
];
products.push(...extraProducts);
products.forEach(p=>{if(p.kind==='belt')p.sizes=['S','M','L'];if(p.kind==='shirt')p.sizes=['S','M','L','XL'];if(p.kind==='shoe')p.sizes=['38','39','40','41','42','43','44']});
let shopState={query:'',category:'all',sort:'default'};
function bundle(){const separate=['belt','wallet','bag'].reduce((sum,id)=>sum+products.find(p=>p.id===id).price,0),price=item('bundle').price;return `<div class="bundle-feature"><div><span class="eyebrow">الحزم — Product Bundling · ثلاث قطع متكاملة</span><h3>حزمة الإطلالة اليومية</h3><p>حزام يومي + محفظة كلاسيكية + حقيبة يومية</p><div class="bundle-prices"><del>${money(separate)}</del><b>${money(price)}</b><span>توفير ${money(separate-price)}</span></div><p class="policy-note">${Date.now()<expiry?'مع خصم الترحيب: '+money(price*.95)+' · يتراكم الخصمان.':'انتهى خصم الترحيب؛ يبقى سعر الحزمة متاحًا.'}</p></div><div class="actions"><button class="btn" data-add="bundle">أضف الحزمة الكاملة +</button><a class="text-link" href="#/strategy/bundles">شرح الاستراتيجية ←</a></div></div>`}
const normalizeArabic=s=>String(s).trim().toLowerCase().normalize('NFKD').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي');
function matchingProducts(state=shopState){let list=products.filter(p=>(state.category==='all'||p.category===state.category)&&normalizeArabic(p.name+' '+p.category+' '+p.desc).includes(normalizeArabic(state.query)));if(state.sort==='asc')list.sort((a,b)=>a.price-b.price);if(state.sort==='desc')list.sort((a,b)=>b.price-a.price);return list}
function storeCatalogue(){return intro('المتجر التجريبي · الدينار الجزائري','اختيارات أكثر، وتجربة أوضح.','12 منتجًا للتطبيق: تصفّح الحقائب والملابس والإكسسوارات ولوازم الدراسة. جميع الأسعار والأمثلة بالدينار الجزائري (د.ج)، وهي أسعار تعليمية افتراضية.')+offer()+`<section class="shop-tools"><div class="search-row"><input id="product-search" type="search" aria-label="ابحث عن منتج" placeholder="ابحث عن حقيبة، ساعة، دفتر…" value="${safe(shopState.query)}"><select id="product-filter" aria-label="تصفية المنتجات"><option value="all">جميع الأقسام</option>${[...new Set(products.map(p=>p.category))].map(c=>`<option ${shopState.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="product-sort" aria-label="ترتيب المنتجات"><option value="default" ${shopState.sort==='default'?'selected':''}>الترتيب الافتراضي</option><option value="asc" ${shopState.sort==='asc'?'selected':''}>السعر: من الأقل للأعلى</option><option value="desc" ${shopState.sort==='desc'?'selected':''}>السعر: من الأعلى للأقل</option></select></div><div class="shop-status"><span id="product-count" role="status">${matchingProducts().length} من ${products.length} منتجًا</span><button class="plain-button" id="reset-products">إعادة ضبط البحث</button><a class="text-link" href="#/images">إدارة صور المنتجات ←</a></div></section><div id="product-results" class="products">${shopResults()}</div><div class="section-head"><h2>اختيار واحد، مجموعة متكاملة</h2><a class="text-link" href="#/strategy/bundles">كيف تعمل الحزم؟ ←</a></div>${bundle()}<section class="store-guide"><div><b>البيع الإضافي — Upselling</b><p>قارن الحقيبة اليومية بحقيبة الظهر الأكبر.</p></div><div><b>البيع المتقاطع — Cross-selling</b><p>أضف دفترًا أو قارورة لحقيبة الدراسة.</p></div><div><b>الحزم — Product Bundling</b><p>راجع التوفير وتكلفة الشحن قبل الاختيار.</p></div></section>`}
function shopResults(){const list=matchingProducts();return list.length?list.map(productCard).join(''):'<div class="empty shop-empty"><h3>لم نجد منتجًا يطابق بحثك</h3><p>جرّب كلمة أخرى أو أعد ضبط القسم والبحث.</p><button class="btn light" id="empty-reset-products">عرض جميع المنتجات ←</button></div>'}
function updateProducts(){if(!$('#product-results'))return;$('#product-results').innerHTML=shopResults();$('#product-count').textContent=`${matchingProducts().length} من ${products.length} منتجًا`}
function resetProducts(){shopState={query:'',category:'all',sort:'default'};$('#product-search').value='';$('#product-filter').value='all';$('#product-sort').value='default';updateProducts()}
function productCard(p){const discounted=Date.now()<expiry;return `<article class="product"><a href="#/product/${p.id}" aria-label="عرض ${p.name}">${visual(p)}</a><div class="product-info"><p>${p.category}</p><h3><a href="#/product/${p.id}">${p.name}</a></h3><div class="price-row"><span class="price">${money(p.price)}</span><a class="text-link" href="#/product/${p.id}">التفاصيل ←</a></div><p class="offer-price">${discounted?'مع الترحيب 5%: '+money(Math.round(p.price*95)/100):'انتهى الخصم الترحيبي'}</p>${p.sizes?`<a class="btn light" href="#/product/${p.id}">اختر المقاس ←</a>`:`<button class="btn light" data-add="${p.id}">+ أضف إلى السلة</button>`}</div></article>`}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return emptyPage();const upgradeId=id==='belt'?'belt-premium':id==='bag'?'backpack':null,upgrade=products.find(x=>x.id===upgradeId);const similar=products.filter(x=>x.id!==id&&x.category===p.category).slice(0,3);const pairIds=['bag','backpack'].includes(id)?['notebook','bottle']:['belt','belt-premium'].includes(id)?['wallet','watch']:['shirt','hoodie'].includes(id)?['cap','belt']:['notebook','bottle'].includes(id)?['bag']:['wallet'];const complements=pairIds.map(x=>products.find(y=>y.id===x)).filter(x=>x&&x.id!==id);return intro('المتجر / تفاصيل المنتج',p.name,p.desc)+`<div class="product-detail">${visual(p)}<div><span class="demo-label">أسعار ومواصفات تعليمية · د.ج</span><h2 style="margin:18px 0">${money(p.price)}</h2>${Date.now()<expiry?`<p class="offer-price">بعد خصم الترحيب: <b>${money(Math.round(p.price*95)/100)}</b></p>`:''}<p class="muted">${p.desc}</p>${p.sizes?`<label class="size-select">${p.kind==='shoe'?'مقاس الحذاء':'المقاس'}<select id="size" aria-label="اختر المقاس">${p.sizes.map(s=>`<option>${s}</option>`).join('')}</select></label>${p.kind==='belt'?'<p class="policy-note">مقاسات الحزام التوضيحية: S‏ (75–85 سم)، M‏ (85–95 سم)، L‏ (95–105 سم).</p>':'<p class="policy-note">المقاسات توضيحية؛ في متجر حقيقي أضف دليل قياس خاصًا بالمنتج.</p>'}`:''}<div class="actions" style="margin:20px 0"><button class="btn" data-add="${p.id}" data-sized="true">أضف إلى السلة +</button><a class="btn light" href="#/cart">عرض السلة</a></div><div class="product-assurance"><span>الشحن العادي ${money(commerce.shipping)}</span><span>مجاني بدءًا من ${money(commerce.freeShippingAt)} بعد الخصم</span><a href="#/strategy/trust">سياسة وتجربة تعليمية ←</a></div></div></div>${upgrade?`<section class="panel related"><span class="eyebrow">البيع الإضافي — Upselling · ترقية اختيارية</span><h2 style="margin-top:12px">هل يناسبك ${upgrade.name}؟</h2><p>${upgrade.desc}</p><p>السعر ${money(upgrade.price)} بدل ${money(p.price)}؛ فرق ${money(upgrade.price-p.price)} قبل الخصم. تستطيع الاحتفاظ بخيارك الحالي.</p><div class="actions"><a class="btn" href="#/product/${upgrade.id}">قارن النسخة الأعلى ←</a><a class="text-link" href="#/strategy/upsell-cross">اقرأ الاستراتيجية ←</a></div></section>`:''}<div class="section-head"><h2>يكمل استخدامك</h2><a class="text-link" href="#/strategy/upsell-cross">البيع المتقاطع — Cross-selling ←</a></div><div class="products">${complements.map(productCard).join('')}</div>${similar.length?`<div class="section-head"><h2>بدائل للمقارنة <bdi class="term-en">Similar Products</bdi></h2><span class="show-all-label">من القسم نفسه، لا يلزم شراؤها معًا</span></div><div class="products">${similar.map(productCard).join('')}</div>`:''}<section class="panel related"><h2>الشحن والاسترجاع بوضوح</h2>${policy()}<a class="text-link" href="#/strategy/trust">افهم بناء الثقة ←</a></section><a class="btn light" href="#/store">→ العودة إلى المنتجات</a>`}
const existingArt=art;
art=function(p){if(!['backpack','hoodie','cap','watch','bottle','notebook'].includes(p.kind))return existingArt(p);const bodies={backpack:`<path d="M103 77V59q52-60 104 0v18" fill="none" stroke="#3c5349" stroke-width="9"/><rect x="82" y="60" width="145" height="140" rx="34" fill="${p.color}"/><rect x="101" y="125" width="106" height="59" rx="13" fill="#445f52"/><path d="M102 137h103M155 63v52" stroke="#becbbb" stroke-width="3"/><rect x="146" y="85" width="20" height="12" rx="3" fill="#d6c6a0"/>`,hoodie:`<path d="M119 68q-5-56 35-56t36 56l49 32-24 43-20-14 8 74h-99l8-74-20 14-23-43Z" fill="${p.color}"/><path d="M122 65q31 31 65 0l-33-37Z" fill="#4d6760"/><path d="M126 155h57l8 29h-73Z" fill="#5a746c"/><path d="M146 80v31m17-31v31" stroke="#e4e4cd" stroke-width="3"/>`,cap:`<path d="M67 146q-1-99 86-99t79 99Z" fill="${p.color}"/><path d="M153 51v91" stroke="#d6bea0" stroke-width="3"/><path d="M66 145q102-35 177 7l-6 19q-98 12-171-26Z" fill="#806b4e"/><circle cx="153" cy="47" r="7" fill="#7d6a50"/>`,watch:`<rect x="129" y="19" width="54" height="201" rx="15" fill="${p.color}"/><circle cx="156" cy="119" r="59" fill="#c5ba9e"/><circle cx="156" cy="119" r="50" fill="#f5f1e6"/><path d="M156 81v38l25 16" fill="none" stroke="#374b42" stroke-width="5"/><circle cx="156" cy="119" r="4" fill="#a77e52"/>`,bottle:`<rect x="129" y="22" width="51" height="25" rx="6" fill="#3e5c52"/><path d="M129 49h51v21q18 15 18 35v84q0 16-16 16h-55q-16 0-16-16v-84q0-20 18-35Z" fill="${p.color}"/><rect x="111" y="107" width="87" height="57" rx="7" fill="#d7e2d1"/><path d="M150 124q-20 20 4 28q23-7-4-28Z" fill="#6a8c7d"/>`,notebook:`<rect x="83" y="31" width="146" height="175" rx="9" fill="#e8e0cc"/><rect x="76" y="26" width="146" height="175" rx="9" fill="${p.color}"/><path d="M99 26v175" stroke="#624a36" stroke-width="8"/><rect x="123" y="76" width="71" height="39" rx="3" fill="#f2e9d5"/><path d="M135 90h47m-47 12h32" stroke="#a79b82" stroke-width="2"/>`};return `<svg viewBox="0 0 310 240" role="img" aria-label="رسم توضيحي: ${p.name}"><ellipse cx="155" cy="215" rx="93" ry="7" fill="#172c1a" opacity=".07"/>${bodies[p.kind]}</svg>`};
document.addEventListener('input',e=>{if(e.target.id==='product-search'){shopState.query=e.target.value;updateProducts()}});
document.addEventListener('change',e=>{if(e.target.id==='product-filter'){shopState.category=e.target.value;updateProducts()}if(e.target.id==='product-sort'){shopState.sort=e.target.value;updateProducts()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&['reset-products','empty-reset-products'].includes(b.id))resetProducts()});

const strategyTerms=[
['البيع الإضافي','Upselling','اقتراح نسخة أعلى قيمة من المنتج نفسه، مثل الترقية من الحقيبة اليومية إلى حقيبة الظهر.','upsell-cross'],
['البيع المتقاطع','Cross-selling','اقتراح منتج مكمل، مثل دفتر أو قارورة مع حقيبة الدراسة.','upsell-cross'],
['حزم المنتجات','Product Bundling','جمع منتجات متكاملة في عرض واحد مع إظهار التوفير.','bundles'],
['حد الشحن المجاني','Free Shipping Threshold','قيمة طلب يجب بلوغها بعد الخصومات للاستفادة من الشحن المجاني.','bundles'],
['العرض محدود المدة','Limited-time Offer','حافز له شروط واضحة وبداية ونهاية حقيقيتان.','offers'],
['الإثبات الاجتماعي','Social Proof','مساعدة الزائر على التقييم عبر آراء وتجارب عملاء حقيقية.','trust'],
['تقليل المخاطرة المدركة','Risk Reversal','توضيح الضمان والاسترجاع والشحن لتقليل مخاوف الشراء.','trust'],
['إعادة الاستهداف','Retargeting','عرض رسالة لاحقة لجمهور مؤهل عبر حملة إعلانية مُعدّة بشكل مناسب.','recovery'],
['استعادة السلات المتروكة','Cart Recovery','تذكير صاحب السلة ومعالجة سبب تردده عبر قناة وافق عليها.','recovery'],
['اختبار أ/ب','A/B Testing','مقارنة نسختين لاختبار فرضية محددة، مع تحليل كافٍ للنتيجة.','measure'],
['الدعوة إلى اتخاذ إجراء','Call to Action (CTA)','عبارة أو زر يوضح الخطوة التالية، مثل إضافة المنتج إلى السلة.','product-page'],
['رسم رحلة العميل','Customer Journey Mapping','توضيح خطوات الزائر وأسئلته وعوائقه من الاكتشاف إلى الشراء.','journey']
];
function terms(){return intro('قاموس البحث · عربي / English','الاسم بالعربية. والمصطلح بالإنجليزية.','مرجع سريع أثناء الدراسة والعرض. اضغط على أي بطاقة لفتح المطلب الذي يشرح الاستراتيجية ويطبّقها.')+`<div class="terms-grid">${strategyTerms.map(([ar,en,desc,id])=>`<a class="term-card" href="#/strategy/${id}"><h2>${ar}</h2><bdi class="term-en">${en}</bdi><p>${desc}</p><span class="text-link">افتح الشرح والتطبيق ←</span></a>`).join('')}</div><div class="nav-pair"><a class="btn light" href="#/learn">→ المباحث والمطالب</a><a class="btn" href="#/store">طبّق في المتجر ←</a></div>`}

function store(){return storeCatalogue()+'<section class="panel" style="margin-top:24px"><h2>الاستراتيجية باسمها العربي والإنجليزي</h2><p>راجع أسماء الاستراتيجيات ومعنى كل منها، ثم انتقل إلى شرحها.</p><a class="btn light" href="#/terms">افتح قاموس الاستراتيجيات — عربي / English ←</a></section><p class="pricing-reference">أسعار الموقع أمثلة تعليمية تقريبية، وليست عروض بيع. للاسترشاد فقط: <a href="https://taibastationery.com/fr/produits/categorie/sacs-a-dos" target="_blank" rel="noopener noreferrer">نماذج أسعار حقائب في متجر جزائري</a>.</p>'}
window.addEventListener('hashchange',render);setInterval(tick,1000);render();

